7	import { renderWithProviders } from '../../../test-utils/render.js';
8	import { Scrollable } from './Scrollable.js';
9	import { Text } from 'ink';
10	import { describe, it, expect, vi, beforeEach } from 'vitest';
11	import * as ScrollProviderModule from '../../contexts/ScrollProvider.js';
12	import { act } from 'react';
13	
14	vi.mock('ink', async (importOriginal) => {
15	  const actual = await importOriginal<typeof import('ink')>();
16	  return {
17	    ...actual,
18	    getInnerHeight: vi.fn(() => 5),
19	    getScrollHeight: vi.fn(() => 10),
20	    getBoundingBox: vi.fn(() => ({ x: 0, y: 0, width: 10, height: 5 })),
21	  };
22	});
23	
24	vi.mock('../../hooks/useAnimatedScrollbar.js', () => ({
25	  useAnimatedScrollbar: (
26	    hasFocus: boolean,
27	    scrollBy: (delta: number) => void,
28	  ) => ({
29	    scrollbarColor: 'white',
30	    flashScrollbar: vi.fn(),
31	    scrollByWithAnimation: scrollBy,
32	  }),
33	}));
34	
35	describe('<Scrollable />', () => {
36	  beforeEach(() => {
37	    vi.restoreAllMocks();
38	  });
39	
40	  it('renders children', async () => {
41	    const { lastFrame, waitUntilReady, unmount } = renderWithProviders(
42	      <Scrollable hasFocus={false} height={5}>
43	        <Text>Hello World</Text>
44	      </Scrollable>,
45	    );
46	    await waitUntilReady();
47	    expect(lastFrame()).toContain('Hello World');
48	    unmount();
49	  });
50	
51	  it('renders multiple children', async () => {
52	    const { lastFrame, waitUntilReady, unmount } = renderWithProviders(
53	      <Scrollable hasFocus={false} height={5}>
54	        <Text>Line 1</Text>
55	        <Text>Line 2</Text>
56	        <Text>Line 3</Text>
57	      </Scrollable>,
58	    );
59	    await waitUntilReady();
60	    expect(lastFrame()).toContain('Line 1');
61	    expect(lastFrame()).toContain('Line 2');
62	    expect(lastFrame()).toContain('Line 3');
63	    unmount();
64	  });
65	
66	  it('matches snapshot', async () => {
67	    const { lastFrame, waitUntilReady, unmount } = renderWithProviders(
68	      <Scrollable hasFocus={false} height={5}>
69	        <Text>Line 1</Text>
70	        <Text>Line 2</Text>
71	        <Text>Line 3</Text>
72	      </Scrollable>,
73	    );
74	    await waitUntilReady();
75	    expect(lastFrame()).toMatchSnapshot();
76	    unmount();
77	  });
78	
79	  it('updates scroll position correctly when scrollBy is called multiple times in the same tick', async () => {
80	    let capturedEntry: ScrollProviderModule.ScrollableEntry | undefined;
81	    vi.spyOn(ScrollProviderModule, 'useScrollable').mockImplementation(
82	      async (entry, isActive) => {
83	        if (isActive) {
84	          capturedEntry = entry as ScrollProviderModule.ScrollableEntry;
85	        }
86	      },
87	    );
88	
89	    const { waitUntilReady, unmount } = renderWithProviders(
90	      <Scrollable hasFocus={true} height={5}>
91	        <Text>Line 1</Text>
92	        <Text>Line 2</Text>
93	        <Text>Line 3</Text>
94	        <Text>Line 4</Text>
95	        <Text>Line 5</Text>
96	        <Text>Line 6</Text>
97	        <Text>Line 7</Text>
98	        <Text>Line 8</Text>
99	        <Text>Line 9</Text>
100	        <Text>Line 10</Text>
101	      </Scrollable>,
102	    );
103	    await waitUntilReady();
104	
105	    expect(capturedEntry).toBeDefined();
106	
107	    if (!capturedEntry) {
108	      throw new Error('capturedEntry is undefined');
109	    }
110	
111	    // Initial state (starts at bottom because of auto-scroll logic)
112	    expect(capturedEntry.getScrollState().scrollTop).toBe(5);
113	
114	    // Call scrollBy multiple times (upwards) in the same tick
115	    await act(async () => {
116	      capturedEntry!.scrollBy(-1);
117	      capturedEntry!.scrollBy(-1);
118	    });
119	    // Should have moved up by 2
120	    expect(capturedEntry.getScrollState().scrollTop).toBe(3);
121	
122	    await act(async () => {
