import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import { GEMINI_DIR } from '../utils/paths.js';

/**
 * A summary of the configuration discovered inside a workspace's `.gemini`
 * directory. Every field is always present; arrays are empty when nothing of
 * that kind was found. This structure is designed to be surfaced to the user
 * in the folder trust dialog so they can make an informed decision before
 * trusting a folder.
 */
export interface FolderDiscoveryResults {
  /** Names of custom commands (`.toml` files without their extension). */
  commands: string[];
  /** Names of configured MCP servers. */
  mcps: string[];
  /** Command strings for any configured hooks. */
  hooks: string[];
  /** Names of discovered skills. */
  skills: string[];
  /** Top-level `settings.json` keys (excluding `mcpServers` and `hooks`). */
  settings: string[];
  /** Human readable warnings about potentially risky configuration. */
  securityWarnings: string[];
  /** Non-fatal errors encountered while scanning the directory. */
  discoveryErrors: string[];
}

interface HookEntry {
  command?: unknown;
}

interface HookDefinitionEntry {
  hooks?: unknown;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Scans a workspace's `.gemini` directory and summarizes its contents so the
 * user can understand what a project configures before choosing to trust it.
 */
export class FolderTrustDiscoveryService {
  /**
   * Discover the configuration contained within `workspaceDir`.
   *
   * If the workspace has no `.gemini` directory, all result arrays are empty
   * and no errors are reported.
   */
  static async discover(workspaceDir: string): Promise<FolderDiscoveryResults> {
    const results: FolderDiscoveryResults = {
      commands: [],
      mcps: [],
      hooks: [],
      skills: [],
      settings: [],
      securityWarnings: [],
      discoveryErrors: [],
    };

    const geminiDir = path.join(workspaceDir, GEMINI_DIR);

    if (!(await FolderTrustDiscoveryService.isDirectory(geminiDir))) {
      return results;
    }

    await FolderTrustDiscoveryService.discoverCommands(geminiDir, results);
    await FolderTrustDiscoveryService.discoverSkills(geminiDir, results);
    await FolderTrustDiscoveryService.discoverSettings(geminiDir, results);

    FolderTrustDiscoveryService.generateSecurityWarnings(results);

    return results;
  }

  private static async isDirectory(dir: string): Promise<boolean> {
    try {
      const stats = await fs.stat(dir);
      return stats.isDirectory();
    } catch {
      return false;
    }
  }

  private static async discoverCommands(
    geminiDir: string,
    results: FolderDiscoveryResults,
  ): Promise<void> {
    const commandsDir = path.join(geminiDir, 'commands');
    try {
      const entries = await fs.readdir(commandsDir, { withFileTypes: true });
      for (const entry of entries) {
        if (entry.isFile() && entry.name.endsWith('.toml')) {
          results.commands.push(path.basename(entry.name, '.toml'));
        }
      }
    } catch {
      // No commands directory is not an error.
    }
  }

  private static async discoverSkills(
    geminiDir: string,
    results: FolderDiscoveryResults,
  ): Promise<void> {
    const skillsDir = path.join(geminiDir, 'skills');
    try {
      const entries = await fs.readdir(skillsDir, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory()) {
          continue;
        }
        const skillFile = path.join(skillsDir, entry.name, 'SKILL.md');
        if (await FolderTrustDiscoveryService.isFile(skillFile)) {
          results.skills.push(entry.name);
        }
      }
    } catch {
      // No skills directory is not an error.
    }
  }

  private static async isFile(filePath: string): Promise<boolean> {
    try {
      const stats = await fs.stat(filePath);
      return stats.isFile();
    } catch {
      return false;
    }
  }

  private static async discoverSettings(
    geminiDir: string,
    results: FolderDiscoveryResults,
  ): Promise<void> {
    const settingsPath = path.join(geminiDir, 'settings.json');

    let content: string;
    try {
      content = await fs.readFile(settingsPath, 'utf-8');
    } catch {
      // No settings.json is not an error.
      return;
    }

    let parsed: unknown;
    try {
      parsed = JSON.parse(content);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      results.discoveryErrors.push(`Failed to discover settings: ${message}`);
      return;
    }

    // Non-object settings (arrays, primitives, null) have no top-level keys to
    // report and are not treated as errors.
    if (!isRecord(parsed)) {
      return;
    }

    FolderTrustDiscoveryService.discoverMcps(parsed, results);
    FolderTrustDiscoveryService.discoverHooks(parsed, results);

    for (const key of Object.keys(parsed)) {
      if (key === 'mcpServers' || key === 'hooks') {
        continue;
      }
      results.settings.push(key);
    }
  }

  private static discoverMcps(
    settings: Record<string, unknown>,
    results: FolderDiscoveryResults,
  ): void {
    const mcpServers = settings['mcpServers'];
    if (isRecord(mcpServers)) {
      results.mcps.push(...Object.keys(mcpServers));
    }
  }

  private static discoverHooks(
    settings: Record<string, unknown>,
    results: FolderDiscoveryResults,
  ): void {
    const hooks = settings['hooks'];
    if (!isRecord(hooks)) {
      return;
    }

    for (const definitions of Object.values(hooks)) {
      if (!Array.isArray(definitions)) {
        continue;
      }
      for (const definition of definitions as HookDefinitionEntry[]) {
        if (!isRecord(definition) || !Array.isArray(definition.hooks)) {
          continue;
        }
        for (const hook of definition.hooks as HookEntry[]) {
          if (isRecord(hook) && typeof hook.command === 'string') {
            results.hooks.push(hook.command);
          }
        }
      }
    }
  }

  private static generateSecurityWarnings(
    results: FolderDiscoveryResults,
  ): void {
    if (results.mcps.length > 0) {
      results.securityWarnings.push(
        'This folder configures MCP servers, which can run external processes and access your data.',
      );
    }
    if (results.hooks.length > 0) {
      results.securityWarnings.push(
        'This folder configures hooks, which automatically run shell commands.',
      );
    }
  }
}
