export enum FolderTrustChoice {
  TRUST_FOLDER = 'trust_folder',
  TRUST_PARENT = 'trust_parent',
  DO_NOT_TRUST = 'do_not_trust',
}

interface FolderTrustDialogProps {
  onSelect: (choice: FolderTrustChoice) => void;
  isRestarting?: boolean;
  discoveryResults?: FolderDiscoveryResults | null;
}

interface DiscoveryGroup {
  label: string;
  items: string[];
}

/** Sanitize a value for display by removing ANSI escape codes. */
const clean = (value: string): string => stripAnsi(value);

const getDiscoveryGroups = (
  results: FolderDiscoveryResults,
): DiscoveryGroup[] =>
  [
    { label: 'Commands', items: results.commands },
    { label: 'MCP Servers', items: results.mcps },
    { label: 'Hooks', items: results.hooks },
    { label: 'Skills', items: results.skills },
    { label: 'Settings', items: results.settings },
  ].filter((group) => group.items.length > 0);

interface DiscoverySummaryProps {
  results: FolderDiscoveryResults;
}

const DiscoverySummary: React.FC<DiscoverySummaryProps> = ({ results }) => {
  const groups = getDiscoveryGroups(results);
  const hasContent = groups.length > 0;

  if (
    !hasContent &&
    results.securityWarnings.length === 0 &&
    results.discoveryErrors.length === 0
  ) {
    return null;
  }

  return (
    <Box flexDirection="column">
      {hasContent && (
        <Box flexDirection="column" marginBottom={1}>
          <Text bold color={theme.text.primary}>
            This folder contains:
          </Text>
          {groups.map((group) => (
            <Text key={group.label} color={theme.text.primary} wrap="wrap">
              <Text bold>{`${group.label} (${group.items.length}): `}</Text>
              {group.items.map((item) => clean(item)).join(', ')}
            </Text>
          ))}
        </Box>
      )}

      {results.securityWarnings.length > 0 && (
        <Box flexDirection="column" marginBottom={1}>
          <Text bold color={theme.status.warning}>
            Security Warnings:
          </Text>
          {results.securityWarnings.map((warning: string, index: number) => (
            <Text key={index} color={theme.status.warning} wrap="wrap">
              {`- ${clean(warning)}`}
            </Text>
          ))}
        </Box>
      )}

      {results.discoveryErrors.length > 0 && (
        <Box flexDirection="column" marginBottom={1}>
          <Text bold color={theme.status.error}>
            Discovery Errors:
          </Text>
          {results.discoveryErrors.map((error: string, index: number) => (
            <Text key={index} color={theme.status.error} wrap="wrap">
              {`- ${clean(error)}`}
            </Text>
          ))}
        </Box>
      )}
    </Box>
  );
};

